INSERT INTO `projects` VALUES (1,'1988-04-06','About NodeSpace','The Space Project','This project aims to develop an online platform that combines a branching knowledge map with rich multimedia resources. Unlike traditional textbooks or linear e-learning modules, this platform encourages exploration and contextual understanding by giving students agency to choose their own learning path and by integrating content from different domains.','This project was funded through the <a href=\"https://humber.ca/about/vision/reimagining-learning/teaching-learning-innovation-fund Builders of Brilliance Teaching & Learning Innovation Fund</a> at Humber Polytechnic.','team.png','2017-01-29',NULL,NULL);
