INSERT INTO `quizzes` VALUES (1,1,1,'easy','The space between model space and camera space is called:','world space',NULL,NULL),(2,1,1,'hard','Umer forgot there is a space in between camera and NDC space. It’s called:','clip space',NULL,NULL),(3,2,2,'easy','How many triangles do you need to make a quad?','2',NULL,NULL),(4,3,3,'easy','The 4th component of a vertex position, known as \"w\", is always set to:','1',NULL,NULL),(5,4,4,'easy','The normal vector [0, 1, 0] is pointing:','Up',NULL,NULL),(6,5,5,'easy','To make a model bigger along all three dimensions, the scale factors in the scale matrix need to be all larger than:','1',NULL,NULL),(7,5,5,'hard','A scale matrix with all three scale factors set to 1 is more commonly known as:','The identity matrix',NULL,NULL),(8,6,6,'easy','The position (1, 2, 3, 1) translated by 1 along x, -2 along y, and 3 along z gives you the final position:','(2, 0, 6, 1)',NULL,NULL),(9,6,6,'hard','Say you are using a 4x4 translation matrix, but you want to switch off translations for a particular vector. You should set the vector’s \"w\" component to:','zero',NULL,NULL),(10,7,7,'easy','The biggest problem with Euler angles is:','Gimbal lock',NULL,NULL),(11,7,7,'hard','The inverse of a rotation matrix is also the following operation on the matrix:','Transpose',NULL,NULL),(12,8,8,'easy','The quaternion k is used to rotate an object 180 degrees about the:','z axis',NULL,NULL),(13,8,8,'hard','Add quaternions to get the average between them, but afterwards don\'t forget to:','normalize',NULL,NULL),(14,8,8,'hard','Invert a quaternion by flipping the sign on the:','i, j, and k parts',NULL,NULL),(15,9,9,'easy','If the matrices for translation (T), rotation (R), and scale (S), are multiplied in the order T * R * S, what transformation occurs first for a position in column vector format:','Scale (S)',NULL,NULL),(16,9,9,'hard','When using the model matrix to transform normals, you need to invert it, transpose it, then remove the fourth column and row. This is important when the scale matrix is:','Non-uniform (or if you are using a shear matrix)',NULL,NULL),(17,10,10,'easy','Each model brought into world space needs its own scale, rotation, and:','translation (or you might say position)',NULL,NULL),(18,10,10,'hard','Say you apply a non-uniform scale and a translation to your model when bringing it into world space. What do you need to do to the model matrix to transform the model’s normals correctly?','inverse transpose it and cast it down to a 3x3 matrix',NULL,NULL),(19,11,11,'easy','If your camera is looking to the left, the view matrix moves the world:','Right',NULL,NULL),(20,11,11,'hard','What’s a quick way of inverting a camera’s rotation matrix?','Transpose it',NULL,NULL),(21,12,12,'easy','If your silly make-believe camera in world space is at position (0, 0, 5), then in camera space the world is translated by:','(0, 0, -5)',NULL,NULL),(22,13,13,'easy','The viewing frustum set up by the projection matrix is shaped like a:','Truncated pyramid (the chopped off apex being the camera position)',NULL,NULL),(23,13,13,'hard','The projection matrix takes vertices from camera space to:','Clip space',NULL,NULL),(24,14,14,'easy','After using the perspective projection matrix, the w component is smallest near the:','Camera\'s front clipping plane',NULL,NULL),(25,14,14,'hard','After using the perspective projection matrix, the w component is used by the GPU to:','Discard geometry outside the view frustum',NULL,NULL),(26,15,15,'easy','The width of the NDC box is:','2 units',NULL,NULL),(27,15,15,'hard','Vulkan uses a right-handed coordinate system for NDC space with positive y going down and x increasing to the right. That means positive z goes:','Away from you',NULL,NULL),(28,16,16,'easy','The viewport matrix stretches the normalized device coordinate box by this much along x:','Half the width of the screen in pixels',NULL,NULL),(29,16,16,'hard','It’s useful to constrain the z coordinate to be between 0.0 and 1.0 rather than -1.0 and 1.0 when going from NDC to pixel space to increase the precision of:','The floating-point distribution',NULL,NULL),(30,17,17,'easy','The origin (0, 0) in pixel space is located at:','The top left corner of the screen',NULL,NULL);
/*!40000 ALTER TABLE `quizzes` ENABLE KEYS */;
UNLOCK TABLES;

