INSERT INTO `topics` VALUES (1,'Intro to Space','intro-to-space','A foundational overview of coordinate spaces and why they matter in 3D graphics pipelines.','#378ADD',690,90,'1','0','0','0','0','','2026-06-02 21:28:23','2026-06-02 21:28:23'),(2,'Model Space','model-space','The local coordinate system of a 3D object, defined relative to its own origin before any transformations are applied.','#F72585',520,190,'1','0','0','0','0','02_model_space','2026-06-02 21:28:23','2026-06-02 21:28:23'),(3,'Vertex Position','vertex-position','The 3D coordinates of each point on a mesh, expressed in model space and used as the basis for all geometric transformations.','#378ADD',95,285,'1','0','0','0','0','03_09_vertex_pos_model_matrix','2026-06-02 21:28:23','2026-06-02 21:28:23'),(4,'Normals','normals','Perpendicular vectors at each vertex surface that define orientation, used in lighting calculations to determine how light interacts with geometry.','#378ADD',430,760,'1','0','0','0','0','4_normal','2026-06-02 21:28:23','2026-06-02 21:28:23'),(5,'Scale','scale','A transformation that resizes an object along one or more axes, applied as a diagonal matrix in model space.','#378ADD',385,400,'1','0','0','0','0','05_scale','2026-06-02 21:28:23','2026-06-02 21:28:23'),(6,'Translation','translation','A transformation that moves an object from one position to another by adding an offset vector to each vertex position.','#378ADD',285,260,'1','0','0','0','0','06_translation','2026-06-02 21:28:23','2026-06-02 21:28:23'),(7,'Rotation','rotation','A transformation that orients an object around an axis by a given angle, typically represented with matrices or quaternions.','#378ADD',190,450,'1','0','0','0','0','07_rotation','2026-06-02 21:28:23','2026-06-02 21:28:23'),(8,'Quaternions','quaternions','A compact 4-component mathematical representation of rotations that avoids gimbal lock and enables smooth interpolation between orientations.','#378ADD',365,530,'1','0','0','0','0','08_quaternions','2026-06-02 21:28:23','2026-06-02 21:28:23'),(9,'Model Matrix','model-matrix','A 4x4 matrix combining scale, rotation, and translation that transforms vertices from model space into world space.','#378ADD',785,250,'1','0','0','0','0','space','2026-06-02 21:28:23','2026-06-02 21:28:23'),(10,'World Space','world-space','A shared global coordinate system where all objects are positioned relative to a common origin after the model matrix is applied.','#F72585',700,455,'1','0','0','0','0','space','2026-06-02 21:28:23','2026-06-02 21:28:23'),(11,'View Matrix','view-matrix','A matrix that transforms world space coordinates into camera space by simulating the position and orientation of the viewer.','#378ADD',930,520,'1','0','0','0','0','11_view_matrix','2026-06-02 21:28:23','2026-06-02 21:28:23'),(12,'Camera Space','camera-space','The coordinate system relative to the camera where the viewer is at the origin, used as an intermediate step before projection.','#F72585',805,675,'1','0','0','0','0','space','2026-06-02 21:28:23','2026-06-02 21:28:23'),(13,'Projection Matrix','projection-matrix','A matrix that maps camera space coordinates onto a 2D projection plane, applying either perspective or orthographic projection.','#378ADD',1060,810,'1','0','0','0','0','13_projection_matrix','2026-06-02 21:28:23','2026-06-02 21:28:23'),(14,'Perspective Divide','perspective-divide','The step that divides x, y, and z components by the w component after projection, converting clip space coordinates into NDC.','#378ADD',345,915,'1','0','0','0','0','14_perspective_divide','2026-06-02 21:28:23','2026-06-02 21:28:23'),(15,'NDC Space','ndc-space','Normalized Device Coordinates — a device-independent coordinate system where all visible geometry falls within a -1 to 1 cube after the perspective divide.','#F72585',640,930,'1','0','0','0','0','space','2026-06-02 21:28:24','2026-06-02 21:28:24'),(16,'Viewport Matrix','viewport-matrix','A matrix that maps NDC coordinates to screen-space pixel coordinates based on the defined viewport dimensions.','#378ADD',940,965,'1','0','0','0','0','16_viewport_matrix','2026-06-02 21:28:24','2026-06-02 21:28:24'),(17,'Pixel Space','pixel-space','The final 2D screen coordinate system where each unit corresponds to a pixel on the display, produced after the viewport transformation.','#378ADD',920,1135,'1','0','0','0','0','space','2026-06-02 21:28:24','2026-06-02 21:28:24'),(18,'Bonus','bonus','Additional supplementary topics and extended concepts beyond the core graphics pipeline for further exploration.','#8B9CB5',500,1110,'1','0','0','0','0','space','2026-06-02 21:28:24','2026-06-02 21:28:24');
/*!40000 ALTER TABLE `topics` ENABLE KEYS */;
UNLOCK TABLES;

