DROP TABLE IF EXISTS `user_video_analytics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_video_analytics` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_video_id` bigint unsigned NOT NULL,
  `interaction_type` enum('Played','Paused','Seeked','Completed','Buffering','RateChange','Volume','Progress','Close') COLLATE utf8mb4_unicode_ci NOT NULL,
  `interact_at` int unsigned NOT NULL,
  `device_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `os_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `browser_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `played_on` date NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_video_analytics_user_video_id_foreign` (`user_video_id`),
  CONSTRAINT `user_video_analytics_user_video_id_foreign` FOREIGN KEY (`user_video_id`) REFERENCES `user_videos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=164 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

