DROP TABLE IF EXISTS `user_video_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_video_settings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `video_id` bigint unsigned NOT NULL,
  `video` tinyint(1) NOT NULL DEFAULT '0',
  `code` tinyint(1) NOT NULL DEFAULT '0',
  `interactive` tinyint(1) NOT NULL DEFAULT '0',
  `rambling` tinyint(1) NOT NULL DEFAULT '0',
  `quiz` tinyint(1) NOT NULL DEFAULT '0',
  `video_checked_with_all` tinyint(1) NOT NULL DEFAULT '0',
  `code_checked_with_all` tinyint(1) NOT NULL DEFAULT '0',
  `interactive_checked_with_all` tinyint(1) NOT NULL DEFAULT '0',
  `rambling_checked_with_all` tinyint(1) NOT NULL DEFAULT '0',
  `quiz_checked_with_all` tinyint(1) NOT NULL DEFAULT '0',
  `all_checked` tinyint(1) NOT NULL DEFAULT '0',
  `watched` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_video_settings_user_id_video_id_unique` (`user_id`,`video_id`),
  KEY `user_video_settings_video_id_foreign` (`video_id`),
  CONSTRAINT `user_video_settings_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `user_video_settings_video_id_foreign` FOREIGN KEY (`video_id`) REFERENCES `videos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
