INSERT INTO `video_sections` VALUES (1,2,'Model Space Part - 2','model-space-part-2','Learn the basics of variables and data types.','thumbnails/section_1.jpg','SpacesProject_V02_ModelSpace_2_exp5_HD.mp4',320,NULL,NULL,'2026-06-02 21:28:25','2026-06-02 21:28:25'),(2,2,'Model Space Part - 3','model-space-part-3','Understand if statements, loops and conditionals.','thumbnails/section_2.jpg','SpacesProject_V02_ModelSpace_3_exp2_HD.mp4',480,NULL,NULL,'2026-06-02 21:28:25','2026-06-02 21:28:25'),(3,2,'Model Space Part - 4','model-space-part-4','Deep dive into functions, closures and variable scope.','thumbnails/section_3.jpg','SpacesProject_V02_ModelSpace_xtra_exp4_HD.mp4',540,NULL,NULL,'2026-06-02 21:28:25','2026-06-02 21:28:25'),(4,3,'Vertex Position -2 ','vertex-position-2','Classes, objects, inheritance and polymorphism explained.','thumbnails/section_4.jpg','SpacesProject_V03_VertexPositions_2_exp1_HD.mp4',720,NULL,NULL,'2026-06-02 21:28:25','2026-06-02 21:28:25'),(5,4,'Normals 2','normals-2','How to catch and handle exceptions gracefully.','thumbnails/section_5.jpg','SpacesProject_V04_Normals_2_exp1_HD.mp4',390,NULL,NULL,'2026-06-02 21:28:25','2026-06-02 21:28:25'),(6,7,'Rotations - 2 ','rotations-2','Connecting to databases and running queries.','thumbnails/section_6.jpg','SpacesProject_V07_Rotation_2_exp3_HD.mp4',610,NULL,NULL,'2026-06-02 21:28:25','2026-06-02 21:28:25'),(7,18,'Bonus - 2','bonus-2','Building and consuming RESTful APIs.','thumbnails/section_7.jpg','SpacesProject_V18_Bonus_2_EXP2_HD.mp4',450,NULL,NULL,'2026-06-02 21:28:25','2026-06-02 21:28:25');
