INSERT INTO `videos` VALUES (1,'Intro to Space','intro-to-space',1,NULL,'https://images.pexels.com/photos/239548/pexels-photo-239548.jpeg','SPACESProj_V01_Introduction_exp9_HD.mp4',12,'An introduction to coordinate spaces in 3D graphics. We explore why different spaces exist and how objects move through them during rendering.','3D graphics use multiple coordinate spaces to transform objects from local mesh data all the way to pixels on screen.','1','1','0','1','1','',NULL,NULL),(2,'Model Space','model-space',2,1,'https://images.pexels.com/photos/2014422/pexels-photo-2014422.jpeg','SpacesProject_V02_ModelSpace_1_exp2_HD.mp4',44,'Model space is the local coordinate system of a 3D object. Every vertex is defined relative to the object\'s own origin before any transformations are applied.','Model space is where your mesh lives before it gets placed into the world — it\'s the object\'s own local coordinate system.','1','1','1','1','1','02_model_space',NULL,NULL),(3,'Vertex Position','vertex-position',3,1,'https://images.pexels.com/photos/1089438/pexels-photo-1089438.jpeg','SpacesProject_V03_VertexPositions_1_exp2_HD.mp4',18,'Vertex positions define the geometry of a 3D mesh. Each vertex holds an XYZ coordinate in model space that gets transformed through the graphics pipeline.','Vertices are the building blocks of 3D geometry — each one is a point in space that gets transformed through the pipeline.','1','1','1','1','1','03_09_vertex_pos_model_matrix',NULL,NULL),(4,'Normals','normals',4,1,'https://images.pexels.com/photos/3862132/pexels-photo-3862132.jpeg','SpacesProject_V04_Normals_1_exp2_HD.mp4',22,'Normal vectors are perpendicular to a surface and are critical for lighting calculations. They must be transformed carefully to remain correct after non-uniform scaling.','Normals tell the GPU which way a surface is facing — essential for lighting to look correct.','1','1','1','1','1','4_normal',NULL,NULL),(5,'Scale','scale',5,1,'https://images.pexels.com/photos/256381/pexels-photo-256381.jpeg','SpacesProject_V05_Scale_exp1_HD.mp4',15,'Scaling transforms change the size of an object along one or more axes. Uniform scaling preserves shape while non-uniform scaling can distort normals.','Scale transforms resize your object — uniform scale keeps the shape intact, non-uniform stretches it.','1','1','1','1','1','05_scale',NULL,NULL),(6,'Translation','translation',6,1,'https://images.pexels.com/photos/4144923/pexels-photo-4144923.jpeg','SpacesProject_V06_Translations_exp2_HD.mp4',34,'Translation moves an object from one position to another in 3D space. In matrix form, translation is encoded in the last column of a 4x4 matrix using homogeneous coordinates.','Translation is how you move objects around the world — represented as the last column in a 4x4 transformation matrix.','1','1','1','1','1','06_translation',NULL,NULL),(7,'Rotation','rotation',7,1,'https://images.pexels.com/photos/924824/pexels-photo-924824.jpeg','SpacesProject_V07_Rotation_1_exp1_HD.mp4',28,'Rotation transforms orient an object in 3D space. Rotations can be represented as Euler angles, rotation matrices, or quaternions, each with trade-offs in interpolation and gimbal lock.','Rotation spins your object in 3D space — Euler angles are intuitive but quaternions are safer for smooth interpolation.','1','1','1','1','1','07_rotation',NULL,NULL),(8,'Quaternions','quaternions',8,7,'https://images.pexels.com/photos/3862601/pexels-photo-3862601.jpeg','SpacesProject_V08_Quaternions_exp5_HD.mp4',38,'Quaternions are a mathematical system used to represent 3D rotations. They avoid gimbal lock and allow smooth interpolation between orientations using SLERP.','Quaternions solve gimbal lock and enable smooth rotation interpolation — the preferred rotation method in game engines.','1','1','1','1','1','08_quaternions',NULL,NULL),(9,'Model Matrix','model-matrix',9,1,'https://images.pexels.com/photos/270348/pexels-photo-270348.jpeg','SpacesProject_V09_ModelMatrix_exp2_HD.mp4',30,'The model matrix combines scale, rotation, and translation into a single 4x4 matrix. Multiplying a vertex by the model matrix transforms it from model space into world space.','The model matrix bundles all your object transforms into one matrix — multiply a vertex by it to place it in the world.','1','1','1','1','1','11_view_matrix',NULL,NULL),(10,'World Space','world-space',10,1,'https://images.pexels.com/photos/1209978/pexels-photo-1209978.jpeg','SpaceProject_V10_WorldSpace_exp11_HD.mp4',20,'World space is the global coordinate system where all objects are placed relative to a shared origin. After applying the model matrix, vertices exist in world space.','World space is the shared stage where all objects coexist — every model matrix transforms into it.','1','1','0','1','1','',NULL,NULL),(11,'View Matrix','view-matrix',11,10,'https://images.pexels.com/photos/1914428/pexels-photo-1914428.jpeg','SpacesProject_V11_View Matrix_exp2_HD.mp4',25,'The view matrix transforms world space coordinates into camera space. It is essentially the inverse of the camera\'s own model matrix, repositioning the world relative to the camera.','The view matrix repositions the entire world so the camera is at the origin looking down the Z axis.','1','1','1','1','1','11_view_matrix',NULL,NULL),(12,'Camera Space','camera-space',12,10,'https://images.pexels.com/photos/225157/pexels-photo-225157.jpeg','SpaceProject_V12_CameraSpace_exp6_HD.mp4',22,'Camera space, also called view space or eye space, positions vertices relative to the camera. The camera sits at the origin looking down the negative Z axis.','Camera space puts the viewer at the center — everything is now relative to where the camera is looking.','1','1','0','1','1','',NULL,NULL),(13,'Projection Matrix','projection-matrix',13,12,'https://images.pexels.com/photos/3938023/pexels-photo-3938023.jpeg','SpaceProject_V13_ProjectionMatrix_exp4_HD.mp4',23,'The projection matrix transforms camera space into clip space. Perspective projection creates a realistic sense of depth while orthographic projection preserves parallel lines.','The projection matrix flattens 3D camera space into 2D clip space — perspective adds depth, orthographic keeps lines parallel.','1','1','1','1','1','13_projection_matrix',NULL,NULL),(14,'Perspective Divide','perspective-divide',14,12,'https://images.pexels.com/photos/2156/sky-earth-space-working.jpg','SpacesProject_V14_PerspectiveDivide_exp4_HD.mp4',23,'The perspective divide divides the X, Y, and Z clip coordinates by the W component to produce normalized device coordinates. This step creates the foreshortening effect of perspective.','Dividing by W is what actually creates perspective — farther objects shrink because their W is larger.','1','1','1','1','1','14_perspective_divide',NULL,NULL),(15,'NDC Space','ndc-space',15,12,'https://images.pexels.com/photos/924824/pexels-photo-924824.jpeg','SpacesProject_V15_NDC Spce_exp2_HD.mp4',18,'Normalized Device Coordinates (NDC) map the visible scene into a cube from -1 to 1 on each axis. Everything outside this range is clipped and not rendered.','NDC is a standardized cube from -1 to 1 — anything outside gets clipped before hitting the screen.','1','1','0','1','1','',NULL,NULL),(16,'Viewport Matrix','viewport-matrix',16,15,'https://images.pexels.com/photos/1714208/pexels-photo-1714208.jpeg','SpacesProject_V16_Viewport_Matrix_exp1_HD.mp4',16,'The viewport transform maps NDC coordinates to pixel coordinates on the screen. It scales and offsets the NDC cube to match the dimensions and position of the render target.','The viewport matrix is the final step — it maps the NDC cube to actual pixel coordinates on your screen.','1','1','1','1','1','16_viewport_matrix',NULL,NULL),(17,'Pixel Space','pixel-space',17,15,'https://images.pexels.com/photos/8471930/pexels-photo-8471930.jpeg','SpaceProject_V17_PixelSpace_exp5_HD.mp4',23,'Pixel space, or screen space, is the final destination of the graphics pipeline. Vertices are now 2D pixel coordinates ready for rasterization and fragment shading.','Pixel space is the end of the pipeline — your 3D scene is now a grid of 2D pixels ready to be drawn.','1','1','0','0','1','',NULL,NULL),(18,'Bonus','bonus',18,NULL,'https://images.pexels.com/photos/3183150/pexels-photo-3183150.jpeg','SpacesProject_V18_Bonus_1_EXP2_HD.mp4',10,'Bonus content covering extra tips and tricks related to the graphics pipeline. Includes practical shader examples and common mistakes to avoid when working with coordinate spaces.','Extra tips and real-world shader examples to solidify your understanding of the full graphics pipeline.','1','0','0','0','0','',NULL,NULL);
